export const INPUT_OPTIONS = {
  service: Object.keys(SERVICES),
  boatType: ["sailboat", "powerboat"],
  hullType: ["monohull", "catamaran", "trimaran"],
  frequency: ["monthly", "bimonthly", "quarterly", "onetime"],
  propellers: { min: 1, max: 4 },
  anodes: { min: 0, max: 10 },
  lengthFeet: { min: 1, max: 200 },
  paintAge: PAINT_AGE_OPTIONS.map((o) => o.value),
  lastCleaned: LAST_CLEANED_OPTIONS.map((o) => o.value),
};

const round2 = (n) => Math.round(n * 100) / 100;

/** Effective growth surcharge for every paint-age × last-cleaned cell, using the
 *  same lookup the estimator uses (empty cells fall through to the next one). */
function growthMatrix() {
  return {
    rows: "lastCleaned",
    columns: "paintAge",
    paintAge: PAINT_AGE_OPTIONS.map(({ value, label }) => ({ value, label })),
    lastCleaned: LAST_CLEANED_OPTIONS.map(({ value, label }) => ({ value, label })),
    cells: LAST_CLEANED_OPTIONS.map(({ value: last }) =>
      PAINT_AGE_OPTIONS.map(({ value: paint }) => {
        const f = lookupFouling(paint, last);
        return { level: f.label, surcharge: f.surcharge };
      })
    ),
  };
}

