/** Parse and validate GET query parameters. */
export function parseQuoteQuery(query = {}) {
  const errors = [];
  const get = (k) => {
    const v = query[k];
    return Array.isArray(v) ? v[0] : v;
  };
  const pick = (key, allowed, fallback) => {
    const raw = get(key);
    if (raw == null || raw === "") return fallback;
    const v = String(raw).trim();
    if (!allowed.includes(v)) {
      errors.push(`${key} must be one of: ${allowed.join(", ")}`);
      return fallback;
    }
    return v;
  };
  const int = (key, { min, max }, fallback) => {
    const raw = get(key);
    if (raw == null || raw === "") return fallback;
    const n = Number(raw);
    if (!Number.isInteger(n) || n < min || n > max) {
      errors.push(`${key} must be a whole number from ${min} to ${max}`);
      return fallback;
    }
    return n;
  };

  const service = pick("service", INPUT_OPTIONS.service, "cleaning");
  // The order form spells one-time as "one_time"; accept both.
  const freq = get("frequency");
  if (freq === "one_time" || freq === "one-time") query = { ...query, frequency: "onetime" };
  const input = {
    service,
    length: int("length", INPUT_OPTIONS.lengthFeet, null),
    boatType: pick("boatType", INPUT_OPTIONS.boatType, "sailboat"),
    hull: pick("hull", INPUT_OPTIONS.hullType, "monohull"),
    frequency: pick("frequency", INPUT_OPTIONS.frequency, "monthly"),
    propellers: int("propellers", INPUT_OPTIONS.propellers, 1),
    anodes: int("anodes", INPUT_OPTIONS.anodes, 0),
    paintAge: pick("paintAge", INPUT_OPTIONS.paintAge, null),
    lastCleaned: pick("lastCleaned", INPUT_OPTIONS.lastCleaned, null),
  };

  const needsLength = ["cleaning", "running_gear", "underwater_inspection"].includes(service);
  if (needsLength && input.length == null && !errors.some((e) => e.startsWith("length"))) {
    errors.push("length is required for this service (boat length in feet)");
  }
  return errors.length ? { ok: false, errors } : { ok: true, input };
}

function orderUrlFor(input, total) {
  const params = new URLSearchParams({
    service: input.service,
    length: String(input.length ?? ""),
    type: input.boatType,
    hull: input.hull,
    frequency: input.frequency === "onetime" ? "one_time" : input.frequency,
    estimate: String(Math.round(total)),
    propellers: String(input.propellers),
    anodes: String(input.anodes),
  });
  if (input.paintAge) params.set("paintAge", input.paintAge);
  if (input.lastCleaned) params.set("lastCleaned", input.lastCleaned);
  return `${ORDER_URL}?${params.toString()}`;
}

/** Quote for validated input. Same math as the /hull-cleaning estimator. */
export function buildQuote(input) {
  const conditionsKnown = Boolean(input.paintAge && input.lastCleaned);
  const calcArgs = {
    serviceKey: input.service,
    boatLength: input.length ?? 35,
    boatType: input.boatType,
    hullType: input.hull,
    frequency: input.frequency,
    propellerCount: input.propellers,
    anodeCount: input.anodes,
    // Unknown conditions price at light growth; the range below shows heavier hulls.
    paintAge: conditionsKnown ? input.paintAge : "<6mo",
    lastCleaned: conditionsKnown ? input.lastCleaned : "<2",
  };
  const est = calculateEstimate(calcArgs);
  const range = conditionPriceRange({
    ...calcArgs,
    paintAge: conditionsKnown ? input.paintAge : "",
    lastCleaned: conditionsKnown ? input.lastCleaned : "",
  });

  return {
    service: { key: input.service, name: SERVICES[input.service].name },
    input,
    estimate: {
      total: round2(est.total),
      currency: "USD",
      per: est.isOneTime ? "one-time service" : "visit",
      startingPrice: Boolean(est.startingPrice),
      minimumApplied: est.minimumApplied,
      lineItems: est.items.map(({ label, detail, amount }) => ({ label, detail, amount: round2(amount) })),
      assumedGrowth: est.fouling
        ? conditionsKnown
          ? { level: est.fouling.label, surcharge: est.fouling.surcharge }
          : { level: "Light (conditions not given)", surcharge: 0 }
        : null,
    },
    conditionRange: range
      ? {
          low: round2(range.rangeLow),
          high: round2(range.rangeHigh),
          expected: range.predictedTier ? range.predictedTier.label : null,
          tiers: range.tiers.map(({ label, surcharge, total }) => ({ label, surcharge, total: round2(total) })),
        }
      : null,
    serviceArea: SERVICE_AREA,
    promotion: PROMOTION,
    notes: ESTIMATE_NOTES,
    orderUrl: orderUrlFor(input, est.total),
    page: PAGE_URL,
    pricing: PRICING_JSON_URL,
  };
}
